//! Windows Service Control Manager host. **NOT VERIFIED ON WINDOWS**
//! (type-checked on other hosts with `host-typecheck`).
//!
//! Replaces the `windows-service` crate, which only builds on Windows: this
//! host is type-checked on every OS (`host-typecheck`), and its `unsafe`
//! blocks are explicit and justified here instead of being generated by a
//! macro. All decisions (accepted controls, status fields, exit codes) live
//! in [`crate::svc_control`] and are unit tested on every OS.
//!
//! This module never installs, configures or starts a service. It only
//! implements the protocol a service process must speak once the SCM has
//! started it.

use std::ffi::c_void;
use std::ptr;
use std::sync::atomic::{AtomicBool, AtomicPtr, AtomicU32, Ordering};
use std::sync::{Arc, OnceLock};

use windows_sys::Win32::Foundation::{ERROR_FAILED_SERVICE_CONTROLLER_CONNECT, GetLastError};
use windows_sys::Win32::System::Services::{
    RegisterServiceCtrlHandlerExW, SERVICE_STATUS, SERVICE_STATUS_HANDLE, SERVICE_TABLE_ENTRYW,
    SetServiceStatus, StartServiceCtrlDispatcherW,
};

use crate::svc_control::{EXIT_CODE_FAILURE, ServiceLifecycle, decide_control, status_fields};

/// Errors starting the dispatcher.
#[derive(Debug, thiserror::Error, PartialEq, Eq)]
pub enum ServiceHostError {
    /// The process was not started by the SCM (e.g. run from a console).
    #[error("not started by the Service Control Manager; use the console mode for development")]
    NotStartedByScm,
    /// `run_dispatcher` was called twice.
    #[error("the service dispatcher can only be started once per process")]
    AlreadyStarted,
    /// Another Win32 failure.
    #[error("{api} failed with Win32 error {code}")]
    Win32 {
        /// Function.
        api: &'static str,
        /// `GetLastError()`.
        code: u32,
    },
}

/// Signals handed to the service body.
#[derive(Clone)]
pub struct ServiceContext {
    /// Set when the SCM requests stop or shutdown.
    pub stop: Arc<AtomicBool>,
    reporter: StatusReporter,
}

impl std::fmt::Debug for ServiceContext {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ServiceContext").finish_non_exhaustive()
    }
}

impl ServiceContext {
    /// Report `Running` once initialisation (database, policy, pipes) is done.
    pub fn report_running(&self) {
        self.reporter.report(ServiceLifecycle::Running, 0);
    }
}

#[derive(Clone, Copy)]
struct StatusReporter;

impl StatusReporter {
    fn report(self, state: ServiceLifecycle, exit_code: u32) {
        let handle: SERVICE_STATUS_HANDLE = STATUS_HANDLE.load(Ordering::SeqCst);
        if handle.is_null() {
            return;
        }
        let checkpoint = CHECKPOINT.fetch_add(1, Ordering::SeqCst).saturating_add(1);
        let f = status_fields(state, checkpoint, exit_code);
        let status = SERVICE_STATUS {
            dwServiceType: f.service_type,
            dwCurrentState: f.current_state,
            dwControlsAccepted: f.controls_accepted,
            dwWin32ExitCode: f.win32_exit_code,
            dwServiceSpecificExitCode: 0,
            dwCheckPoint: f.checkpoint,
            dwWaitHint: f.wait_hint_ms,
        };
        // SAFETY: `handle` was returned by RegisterServiceCtrlHandlerExW for
        // this process (non-null checked above) and is valid until the
        // process exits; `status` is a fully initialised SERVICE_STATUS that
        // lives for the duration of the call. The handle must not be closed.
        unsafe {
            SetServiceStatus(handle, &status);
        }
    }
}

type ServiceBody = Box<dyn Fn(ServiceContext) -> Result<(), String> + Send + Sync>;

static BODY: OnceLock<ServiceBody> = OnceLock::new();
static NAME: OnceLock<Vec<u16>> = OnceLock::new();
static STOP: OnceLock<Arc<AtomicBool>> = OnceLock::new();
static STATUS_HANDLE: AtomicPtr<c_void> = AtomicPtr::new(ptr::null_mut());
static CHECKPOINT: AtomicU32 = AtomicU32::new(0);

fn wide(s: &str) -> Vec<u16> {
    s.encode_utf16().chain(std::iter::once(0)).collect()
}

/// Control handler registered with `RegisterServiceCtrlHandlerExW`.
unsafe extern "system" fn control_handler(
    control: u32,
    _event_type: u32,
    _event_data: *mut c_void,
    _context: *mut c_void,
) -> u32 {
    let d = decide_control(control);
    if d.request_stop
        && let Some(stop) = STOP.get()
    {
        stop.store(true, Ordering::SeqCst);
    }
    if d.report_stop_pending {
        StatusReporter.report(ServiceLifecycle::StopPending, 0);
    }
    d.handler_result
}

/// `ServiceMain` called by the dispatcher on its own thread.
unsafe extern "system" fn service_main(_argc: u32, _argv: *mut windows_sys::core::PWSTR) {
    let (Some(name), Some(body), Some(stop)) = (NAME.get(), BODY.get(), STOP.get()) else {
        return;
    };
    // SAFETY: `name` is a NUL-terminated UTF-16 string in a static that is
    // never mutated; `control_handler` matches LPHANDLER_FUNCTION_EX; a null
    // context is permitted because the handler uses statics.
    let handle =
        unsafe { RegisterServiceCtrlHandlerExW(name.as_ptr(), Some(control_handler), ptr::null()) };
    if handle.is_null() {
        return;
    }
    STATUS_HANDLE.store(handle, Ordering::SeqCst);
    let reporter = StatusReporter;
    reporter.report(ServiceLifecycle::StartPending, 0);
    let ctx = ServiceContext {
        stop: Arc::clone(stop),
        reporter,
    };
    let exit = match body(ctx) {
        Ok(()) => 0,
        Err(_) => EXIT_CODE_FAILURE,
    };
    reporter.report(ServiceLifecycle::Stopped, exit);
}

/// Connect to the SCM and run `body` as the service `name`. Blocks until
/// the service stops. The body must call [`ServiceContext::report_running`]
/// after initialisation and return when `stop` becomes true.
pub fn run_dispatcher(
    name: &str,
    body: impl Fn(ServiceContext) -> Result<(), String> + Send + Sync + 'static,
) -> Result<(), ServiceHostError> {
    if BODY.set(Box::new(body)).is_err() {
        return Err(ServiceHostError::AlreadyStarted);
    }
    let name_w = NAME.get_or_init(|| wide(name));
    let _ = STOP.set(Arc::new(AtomicBool::new(false)));
    // The dispatcher only reads the name; a mutable pointer is required by
    // the struct definition.
    let table = [
        SERVICE_TABLE_ENTRYW {
            lpServiceName: name_w.as_ptr().cast_mut(),
            lpServiceProc: Some(service_main),
        },
        SERVICE_TABLE_ENTRYW {
            lpServiceName: ptr::null_mut(),
            lpServiceProc: None,
        },
    ];
    // SAFETY: `table` is a null-terminated SERVICE_TABLE_ENTRYW array that
    // outlives the call (the call blocks until all services stop); the name
    // points into a static. `service_main` matches LPSERVICE_MAIN_FUNCTIONW.
    let ok = unsafe { StartServiceCtrlDispatcherW(table.as_ptr()) };
    if ok != 0 {
        return Ok(());
    }
    // SAFETY: GetLastError has no preconditions.
    let code = unsafe { GetLastError() };
    if code == ERROR_FAILED_SERVICE_CONTROLLER_CONNECT {
        Err(ServiceHostError::NotStartedByScm)
    } else {
        Err(ServiceHostError::Win32 {
            api: "StartServiceCtrlDispatcherW",
            code,
        })
    }
}
